import json, sys
payload = {'probe': 'exp3247_cuda_bindings_probe', 'python_version': sys.version}
try:
    import cuda.bindings.runtime as rt
    err, count = rt.cudaGetDeviceCount()
    runtime_err, runtime_version = rt.cudaRuntimeGetVersion()
    driver_err, driver_version = rt.cudaDriverGetVersion()
    ok = str(err).endswith('cudaSuccess') and bool(count and count > 0)
    names = []
    if ok:
        for idx in range(int(count)):
            prop_err, prop = rt.cudaGetDeviceProperties(idx)
            if str(prop_err).endswith('cudaSuccess'):
                raw_name = getattr(prop, 'name', b'')
                name = raw_name.decode('utf-8', 'replace').rstrip('\x00') if isinstance(raw_name, bytes) else str(raw_name)
                names.append(name)
    payload.update({'cuda_bindings_import_ok': True, 'cuda_bindings_runtime_ok': ok, 'cuda_bindings_device_count': int(count or 0) if ok else 0, 'cuda_bindings_raw_device_count': int(count or 0), 'cuda_bindings_device_names': names, 'cuda_bindings_cuda_error': str(err), 'cuda_bindings_runtime_version': runtime_version if str(runtime_err).endswith('cudaSuccess') else None, 'cuda_bindings_driver_version': driver_version if str(driver_err).endswith('cudaSuccess') else None})
except Exception as exc:
    payload.update({'cuda_bindings_import_ok': False, 'cuda_bindings_runtime_ok': False, 'cuda_bindings_device_count': 0, 'cuda_bindings_raw_device_count': 0, 'cuda_bindings_device_names': [], 'cuda_bindings_cuda_error': f'{type(exc).__name__}: {exc}', 'cuda_bindings_runtime_version': None, 'cuda_bindings_driver_version': None})
print(json.dumps(payload, sort_keys=True))

